bool Gecko_HasActiveViewTransitionTypes(
    const mozilla::dom::Document* aDoc,
    const nsTArray<StyleCustomIdent>* aNames) {
  MOZ_ASSERT(aDoc);
  MOZ_ASSERT(aNames);
  const ViewTransition* vt = aDoc->GetActiveViewTransition();
  if (!vt) {
    return false;
  }
  const auto& typeList = vt->GetTypeList();
  if (typeList.IsEmpty()) {
    return false;
  }
  for (const auto& name : *aNames) {
    if (typeList.Contains(name.AsAtom())) {
      // NOTE(emilio): This IsValidViewTransitionType() check is not in the spec
      // and is rather weird, but matches other browsers for now, see:
      // https://github.com/w3c/csswg-drafts/issues/13141
      if (IsValidViewTransitionType(name.AsAtom())) {
        return true;
      }
    }
  }
  return false;
}

static bool IsValidViewTransitionType(nsAtom* aName) {
  nsDependentAtomString str(aName);
  return !StringBeginsWith(str, u"-ua-"_ns,
                           nsASCIICaseInsensitiveStringComparator) &&
         !str.LowerCaseEqualsASCII("none");
}

NonTSPseudoClass::ActiveViewTransitionType(ref types) => {
                self.state().intersects(pseudo_class.state_flag())
                    && unsafe {
                        bindings::Gecko_HasActiveViewTransitionTypes(
                            self.as_node().owner_doc().0,
                            types,
                        )
                    }
            }

pub fn state_flag(&self) -> ElementState {
    macro_rules! flag {
        (_) => {
            ElementState::empty()
        };
        ($state:ident) => {
            ElementState::$state
        };
    }
    macro_rules! pseudo_class_state {
        ([$(($css:expr, $name:ident, $state:tt, $flags:tt),)*]) => {
            match *self {
                $(NonTSPseudoClass::$name => flag!($state),)*
                NonTSPseudoClass::Dir(ref dir) => dir.element_state(),
                NonTSPseudoClass::Heading(..) => ElementState::HEADING_LEVEL_BITS,
                NonTSPseudoClass::ActiveViewTransitionType(..) => ElementState::ACTIVE_VIEW_TRANSITION,
                NonTSPseudoClass::MozLocaleDir(..) |
                NonTSPseudoClass::CustomState(..) |
                NonTSPseudoClass::Lang(..) => ElementState::empty(),
            }
        }
    }
    apply_non_ts_list!(pseudo_class_state)
}

[[nodiscard]] bool EnsureInserted(KeyType aKey,
                                  EntryType** aEntry = nullptr) {
  auto oldCount = Count();
  EntryType* entry = PutEntry(aKey);
  if (aEntry) {
    *aEntry = entry;
  }
  return oldCount != Count();
}

bool Equals(char16ptr_t aString, uint32_t aLength) const {
  return mLength == aLength &&
         memcmp(GetUTF16String(), aString, mLength * sizeof(char16_t)) == 0;
}

bool Equals(const nsAtom* aAtom) const {
  if (mUTF8String) {
    return CompareUTF8toUTF16(
               nsDependentCSubstring(mUTF8String, mUTF8String + mLength),
               nsDependentAtomString(aAtom)) == 0;
  }
  return aAtom->Equals(mUTF16String, mLength);
}

already_AddRefed<nsAtom> nsAtomTable::GetOrInsert(const nsAString& aUTF16String,
                                                  AtomTableKey& aKey) {
  nsAtomSubTable& table = SelectSubTable(aKey);
  {
    AutoReadLock lock(table.mLock);
    if (AtomTableEntry* he = table.Search(aKey)) {
      return do_AddRef(he->mAtom);
    }
  }

  AutoWriteLock lock(table.mLock);
  AtomTableEntry* he = table.Add(aKey);
  if (he->mAtom) {
    return do_AddRef(he->mAtom);
  }
  RefPtr<nsAtom> newAtom =
      dont_AddRef(nsDynamicAtom::Create(aUTF16String, aKey.mHash));
  he->mAtom = newAtom;
  return newAtom.forget();
}

already_AddRefed<nsAtom> nsAtomTable::AtomizeMainThread(
    const nsAString& aUTF16String) {
  MOZ_ASSERT(NS_IsMainThread());

  size_t length = aUTF16String.Length();
  const char16_t* str = aUTF16String.Data();

  if (auto sig = ShortAtomCache::TryMakeSignature(str, length)) {
    if (nsAtom* cached = sShortAtomCache.Lookup(sig)) {
      return do_AddRef(cached);
    }
    AtomTableKey key(str, length);
    RefPtr<nsAtom> retVal = GetOrInsert(aUTF16String, key);
    sShortAtomCache.Put(sig, retVal);
    return retVal.forget();
  }

  AtomTableKey key(str, length);
  RefPtr<nsAtom> retVal;
  auto p = sRecentlyUsedMainThreadAtoms.Lookup(key);
  if (p) {
    retVal = p.Data();
  } else {
    retVal = GetOrInsert(aUTF16String, key);
    p.Set(retVal);
  }
  return retVal.forget();
}

already_AddRefed<nsAtom> NS_AtomizeMainThread(const nsAString& aUTF16String) {
  MOZ_ASSERT(gAtomTable);
  return gAtomTable->AtomizeMainThread(aUTF16String);
}

[[nodiscard]] index_type IndexOf(const Item& aItem, index_type aStart,
                                 const Comparator& aComp) const {
  ::detail::CompareWrapper comp(aComp);

  const value_type* iter = Elements() + aStart;
  const value_type* iend = Elements() + Length();
  for (; iter != iend; ++iter) {
    if (comp.Equals(*iter, aItem)) {
      return index_type(iter - Elements());
    }
  }
  return NoIndex;
}

bool RemoveElement(const Item& aItem, const Comparator& aComp) {
  index_type i = IndexOf(aItem, 0, aComp);
  if (i == NoIndex) {
    return false;
  }
  RemoveElementsAtUnsafe(i, 1);
  return true;
}

bool RemoveElement(const Item& aItem) {
  return RemoveElement(aItem, nsDefaultComparator<value_type, Item>());
}
